    func test_dot_inner() {
        for (name, x) in layoutVariants(V4){
            XCTAssertClose(Matft.dot(x, V4), MfArray([169.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.dot(x, V4) \(name)")
