    func test_cross() {
        for (name, x) in layoutVariants(P3){
            XCTAssertClose(Matft.cross(x, Q3), MfArray([-2.0, -5.0, -1.0, -5.0, 0.0, 3.0, 12.0, 6.0, -13.0, -1.0, 1.0, 0.0] as [Double], mftype: .Double, shape: [4, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.cross(x, Q3) \(name)")
        }
        for (name, x) in layoutVariants(Q3){
            XCTAssertClose(Matft.cross(P3, x), MfArray([-2.0, -5.0, -1.0, -5.0, 0.0, 3.0, 12.0, 6.0, -13.0, -1.0, 1.0, 0.0] as [Double], mftype: .Double, shape: [4, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.cross(P3, x) \(name)")
        }
        XCTAssertClose(Matft.cross(P3I, Q3I), MfArray([-2, -5, -1, -5, 0, 3, 12, 6, -13, -1, 1, 0] as [Int], mftype: .Int, shape: [4, 3]), rtol: 0, atol: 0, checkType: true, "Matft.cross(P3I, Q3I)")
        for (name, x) in layoutVariants(P3){
            XCTAssertClose(Matft.cross(x, MfArray([1, -1, 2] as [Double])), MfArray([-2.0, -4.0, -1.0, 13.0, -1.0, -7.0, 4.0, 2.0, -1.0, 1.0, 1.0, -0.0] as [Double], mftype: .Double, shape: [4, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.cross(x, MfArray([1, -1, 2] as [Double])) \(name)")
        }
        XCTAssertClose(Matft.cross(MfArray([1, 0, 0] as [Double]), MfArray([0, 1, 0] as [Double])), MfArray([0.0, 0.0, 1.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.cross(MfArray([1, 0, 0] as [Double]), MfArray([0, 1, 0] as [Double]))")
        for (name, x) in layoutVariants(P2){
            XCTAssertClose(Matft.cross(x, Q2), MfArray([1.0, -5.0, 15.0] as [Double], mftype: .Double, shape: [3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.cross(x, Q2) \(name)")
        }
    }

