    #if !os(WASI)
    func test_complex_broadcast_empty_alias() {
        for (name, x) in [("contiguous", Z), ("column", Z.to_contiguous(mforder: .Column)), ("offset view", Z_pad[1~<4]), ("prefix view", Z_pre[0~<3]), ("strided view", Z_str[0~<6~<2]), ("reversed view", Z_rev[Matft.reverse]), ("transposed view", Z_t.T)] as [(String, MfArray)]{
            do {
                let ret = x + WROW
                XCTAssertTrue(ret.isComplex, "not complex: x + WROW \(name)")
                XCTAssertClose(ret.real, MfArray([1.5, -0.7, 1.0, 2.0, -2.0, 0.5, 0.5, 1.75, 5.0, -1.5, -0.25, 3.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "real: x + WROW \(name)")
                XCTAssertClose(ret.imag ?? MfArray([Double.nan]), MfArray([-1.7, 1.3, 2.0, 0.0, -6.0, -1.5, 3.0, 2.5, -1.0, 0.0, 0.0, 1.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "imag: x + WROW \(name)")
            }
        }
        for (name, x) in [("contiguous", Z), ("column", Z.to_contiguous(mforder: .Column)), ("offset view", Z_pad[1~<4]), ("prefix view", Z_pre[0~<3]), ("strided view", Z_str[0~<6~<2]), ("reversed view", Z_rev[Matft.reverse]), ("transposed view", Z_t.T)] as [(String, MfArray)]{
            do {
                let ret = x * WCOL
                XCTAssertTrue(ret.isComplex, "not complex: x * WCOL \(name)")
                XCTAssertClose(ret.real, MfArray([1.1, 0.40000000000000013, 0.0, 0.0, 4.0, 2.0, 0.0, -2.5, -3.0, 1.5, -3.75, 0.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "real: x * WCOL \(name)")
                XCTAssertClose(ret.imag ?? MfArray([Double.nan]), MfArray([-0.7, 3.2, -5.0, 0.0, -3.0, 0.0, 1.5, -0.25, -5.0, 2.5, 2.25, -2.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "imag: x * WCOL \(name)")
